import {scienceGames,freshScience,checkScience} from './science-games.mjs';
import {scienceArt} from './science-art.mjs';
export function renderScience(root,state,id,finish){
 const game=scienceGames[id],s=state.science??=freshScience(),q=game.steps[s.step],a=s.answers[s.step];
 const on=(selector,fn)=>root.querySelector(selector)?.addEventListener('click',fn);
 const draw=(target='#science-title')=>{renderScience(root,state,id,finish);root.querySelector(target)?.focus();};
 if(s.page==='guide'){
 root.innerHTML=`<div class="science-studio"><p class="eyebrow">${game.name} · CUATRO MISIONES PARA CONECTAR</p><h4 id="science-title" tabindex="-1">Mira. Elige. Explica una conexión.</h4><div class="science-tutorial"><div>${scienceArt(id==='biology'?'plant':'clear')}</div><div><p>${game.guide}</p><p class="offline-idea">${game.example}</p><ol><li>Lee el registro: el dibujo por sí solo no cuenta todo.</li><li>Selecciona una ficha y una razón. Toca o usa Tab y Enter/Espacio; no hace falta arrastrar.</li><li>Revisa la conexión y prueba otra idea si lo necesitas.</li></ol></div></div><p>Sin puntos ni cronómetro. Puedes explorar una misión, cambiar de misión o terminar cuando quieras.</p><button type="button" class="action primary" id="science-start">Explorar las misiones</button></div>`;
 on('#science-start',()=>{s.page='play';draw();});return;
 }
 const result=a.checked&&a.choice&&a.reason?checkScience(id,s.step,a.choice,a.reason):null;
 root.innerHTML=`<div class="science-studio"><nav class="science-map" aria-label="Misiones de ${game.name}">${game.steps.map((step,i)=>`<button type="button" class="action secondary" data-science-step="${i}" aria-current="${i===s.step?'step':'false'}">${i+1}. ${step.title}${s.answers[i].checked?' · Revisada':''}</button>`).join('')}</nav><p class="eyebrow">${game.name} · MISIÓN ${s.step+1} DE ${game.steps.length}</p><h4 id="science-title" tabindex="-1">${q.title}</h4><div class="science-observation">${q.art?scienceArt(q.art):''}<div><strong>Registro de observación</strong><p id="science-observation">${q.observation}</p><span class="quiet">Ilustración y caso didácticos; no es una medición tuya.</span></div></div><fieldset aria-describedby="science-observation"><legend>1. ${q.prompt}</legend><div class="science-choices">${q.options.map(c=>`<button type="button" class="science-choice" data-science-choice="${c.id}" aria-pressed="${a.choice===c.id}">${c.art?scienceArt(c.art):`<span class="science-group" aria-hidden="true">${c.id==='living'?'●':c.id==='once'?'◐':'○'}</span>`}<strong>${c.label}</strong>${c.art?`<span>${c.feedback}</span>`:''}<span class="science-selected">${a.choice===c.id?'Seleccionada':'Seleccionar ficha'}</span></button>`).join('')}</div></fieldset><fieldset><legend>2. ¿Qué observación justifica la conexión?</legend><div class="answer-options">${q.reasons.map(r=>`<button type="button" class="answer-option" data-science-reason="${r.id}" aria-pressed="${a.reason===r.id}">${r.label}</button>`).join('')}</div></fieldset><p class="science-connection"><strong>Tu conexión:</strong> ${q.options.find(c=>c.id===a.choice)?.label||'Elige una ficha'} <span aria-hidden="true">—</span> ${q.reasons.find(r=>r.id===a.reason)?.label||'Elige una razón'}</p><div class="controls"><button type="button" class="action primary" id="science-check">Revisar mi conexión</button><button type="button" class="action secondary" id="science-retry">Volver a intentar esta misión</button><button type="button" class="action secondary" id="science-hint">Una pista</button></div><div id="science-feedback" class="feedback" role="status" aria-live="polite" aria-atomic="true">${result?`<strong>${result.correct?'La conexión se apoya en el registro.':'Revisa qué evidencia apoya el objetivo.'}</strong> ${result.feedback}`:''}</div><div class="controls"><button type="button" class="action secondary" id="science-next">${s.step<game.steps.length-1?'Opcional: siguiente misión':'Cerrar y llevar una idea fuera de pantalla'}</button><button type="button" class="action secondary" id="science-guide">Volver a la guía</button></div><p class="quiet">Puedes pasar a otra misión aunque no hayas respondido. No evaluamos opiniones ni capacidades.</p></div>`;
 root.querySelectorAll('[data-science-step]').forEach(b=>b.addEventListener('click',()=>{s.step=Number(b.dataset.scienceStep);draw();}));
 for(const [data,field] of [['choice','choice'],['reason','reason']])root.querySelectorAll(`[data-science-${data}]`).forEach(b=>b.addEventListener('click',()=>{a[field]=b.getAttribute('data-science-'+data);a.checked=false;draw(`[data-science-${data}="${a[field]}"]`);}));
 on('#science-check',()=>{if(!a.choice||!a.reason){root.querySelector('#science-feedback').textContent='Elige una ficha y una razón para conectar ambas. Puedes consultar una pista o pasar de misión.';return;}a.checked=true;draw('#science-check');});
 on('#science-retry',()=>{s.answers[s.step]={choice:null,reason:null,checked:false};draw();});
 on('#science-hint',()=>{root.querySelector('#science-feedback').textContent=q.hint;});
 on('#science-next',()=>{if(s.step===game.steps.length-1){finish();return;}s.step++;draw();});
 on('#science-guide',()=>{s.page='guide';draw();});
}
